BOOL
cPLAYER_DATA::Init()
{
	return	TRUE;
}

void
cPLAYER_DATA::getAvatarData(cAVATAR_INFO *_lpAvataInfo)
{
	strcpy(_lpAvataInfo->m_strName,m_strName);
	_lpAvataInfo->m_wJob		=	m_wJob;
	_lpAvataInfo->m_wLevel		=	m_iLevel;

	if (m_wJob%2==0)
			_lpAvataInfo->m_wWeapon	=	m_aEquip[dEQUIP_WEAPON].m_wBaseItem;
	else	_lpAvataInfo->m_wWeapon	=	m_aEquip[dEQUIP_WEAPON_2].m_wBaseItem;

	_lpAvataInfo->m_wShield		=	m_aEquip[dEQUIP_SHIELD_BULLET].m_wBaseItem;
	_lpAvataInfo->m_wArmor		=	m_aEquip[dEQUIP_ARMOR].m_wBaseItem;
	_lpAvataInfo->m_wLastField	=	m_wCurrentField;
	_lpAvataInfo->m_wAvatarIndex=	m_wAvatarIndex;
}

void
cPLAYER_DATA::initializeJobData(char *_strId,char *_strName,int _iJob,int _iField,int _iServerType)
{
	memcpy(this,&g_aPlayerDefaultJobData[_iJob],sizeof(cPLAYER_DATA));

	strcpy(m_strId,_strId);
	strcpy(m_strName,_strName);

	m_iXPos			=	-1;
	m_iYPos			=	-1;

	m_wLastVillage	=	0;

	if	(_iField	!=	-1)
		m_wCurrentField	=	_iField;//현재 필드

	if	(_iServerType	==	eSERVER_TYPE_DUEL)
	{
		m_iGold	=	c_iDefaultGoldForDuelPlayer;

		for (int i=0;i<dEQUIPMENT_PART_COUNT;i++)
			m_aEquip[i].reset();

		m_aItems[0].reset();
		
		m_wCurrentField	=	c_iDuelServerLobyIndex;
		m_wLastVillage	=	c_iDuelServerLobyIndex;
	}
}

//
//	각 직업의 디폴트 데이터를 읽어 들인다.
BOOL
LoadDefaultPlayerData(char *fn)
{
	FILE *fp;

	fp	=	fopen(fn,"rb");

	if	(!fp)
	{
		MessageBox(GetActiveWindow(),"can not find 'defaultJob.dat' file","error!!",MB_OK);
		return	FALSE;
	}

	fread(g_aPlayerDefaultJobData,sizeof(g_aPlayerDefaultJobData),1,fp);

	fclose(fp);

	for	(int i=0;i<dPLAYER_JOB_COUNT;i++)
	{
		if	(g_aPlayerDefaultJobData[i].m_wJob	!=	i)
		{
			MessageBox(GetActiveWindow(),"incorrect 'defaultJob.dat' file\n\nupdate 'defaultJob.dat' file","error!!",MB_OK);
			return	FALSE;
		}
	}

	return	TRUE;
}

int
GetSkillIndex(int _iSkill)
{
	int	aSkillIndex[80]	=	
	{
	  0,  0 ,// 수직 베기
	  1,  1 ,// 수평 베기
	  2,  2 ,// 사선 베기
	  3,  3 ,// 찌르기
	  4,  4 ,// 와일드 댄스
	  5, 25 ,// 내려치기
	  6, 26 ,// 이단 내려치기
	  7, 27 ,// 브로드 블레이드
	  8, 28 ,// 소닉 블레이드
	  9, 29 ,// 딜레이 크러싱
	 10, 30 ,// 스트레이트 스파이크
	 11,100 ,// 후려치기
	 12,101 ,// 쏜 스매싱
	 13,102 ,// 엑소시즘 인카운터
	 14,103 ,// 가즈 핸드
	 15,125 ,// 텔레키네시스
	 16,126 ,// 블레스드 해머
	 17,127 ,// 헤븐리 프레싱
	 18,128 ,// 페더 니들
	 19,129 ,// 홀리 서클
	 20,130 ,// 블러디 윙
	 21,225 ,// 창 찌르기
	 22,226 ,// 데저트 블래스트
	 23,227 ,// 래피드 스팅거
	 24,228 ,// 투창
	 25,229 ,// 일루젼 스피어
	 26,230 ,// 자벨린 템페스트
	 27,200 ,// 화살 쏘기
	 28,201 ,// 스타틀링 라이너
	 29,202 ,// 피어싱 애로우
	 30,203 ,// 스나이프
	 31,204 ,// 스컬 페니트레이터
	 0xffff,
	};

	int	iIndex	=	0;

	while(1)
	{
		if	(aSkillIndex[iIndex*2]	==	_iSkill)
			return	aSkillIndex[iIndex*2+1];

		if	(aSkillIndex[iIndex*2]	==	0xffff)
			break;

		iIndex	++;
	}

	return	-1;
}

//
//	
void
cPLAYER_DATA::rebuildSkillInfo()
{
	for (int i=0;i<dABILITY_COUNT;i++)
	{
		CAbilityDefine	*lpAbility	=	&m_aAbility[i];

		if	(lpAbility->m_wSkill	==	0xffff)
			continue;

		int	iSkill	=	GetSkillIndex(lpAbility->m_wSkill);

		if	(iSkill	==	0xffff)	
		{
			printf("에러!!\n%d -> %d\n",lpAbility->m_wSkill,iSkill);
			getch();
		}

		printf("%d -> %d\n",lpAbility->m_wSkill,iSkill);

		lpAbility->m_wSkill		=	iSkill;
	}
}


//
//	스킬 포인트로 레벨을 얻어온다.
BOOL
cPLAYER_DATA::getLevelBySkillPoint(int *_lpiLevel,int *_lpiExp,int *_lpiSkillPoint)
{
	int	iSkillPoint	=	m_dwSkillExperience;

	for (int i=0;i<dABILITY_COUNT;i++)
	{
		if (m_aAbility[i].m_wSkill	==	0xffff	)	continue;
		if (m_aAbility[i].m_wLevel	==	0		)	continue;

		int	iPoint	=	((cABILITY*)&m_aAbility[i])->getSkillPoint();

		iSkillPoint	+=	iPoint;
	}

	if (iSkillPoint	>	0)	iSkillPoint--;	//	가장 기본 스킬

	*_lpiSkillPoint	=	iSkillPoint;

	int	iLevel	=	1;

	while(1)
	{
		int	iRequirePoint	=	min(iLevel+1,100);
		if (iSkillPoint	<	iRequirePoint)	break;

		iLevel++;
		iSkillPoint	-=	iRequirePoint;
	}

	*_lpiLevel	=	iLevel;
	*_lpiExp	=	iSkillPoint*g_aExpTable[iLevel+1]/(iLevel+1);

	return	TRUE;
}

//
//	스킬 데이터가 정상인지 확인
BOOL
cPLAYER_DATA::isCorrectSkillData()
{
	if (m_aAbility[0].m_wSkill	==	0xffff	)	return	FALSE;
	if (m_aAbility[0].m_wLevel	<=	0		)	return	FALSE;

	for (int i=0;i<dABILITY_COUNT;i++)
	{
		cABILITY	*lpAbility		=	(cABILITY *)&m_aAbility[i];

		if (lpAbility->m_wSkill		==	0xffff		)	continue;
		if (lpAbility->m_wSkill		>	dMAX_SKILL	)	return	FALSE;
		if (lpAbility->m_wLevel		>	50			)	return	FALSE;
		if (lpAbility->m_wSkill/50	!=	m_wJob/2	)	return	FALSE;
	}

	return	TRUE;
}

//
//	빈 아이템 슬롯 찾기
int
cPLAYER_DATA::getValidItemSlot()
{
	for (int i=0;i<getInventorySize();i++)
		if (m_aItems[i].m_wBaseItem	==	0xffff)
			return	i;

	return	0xffff;
}

//
//	현재 스킬포인트의 합
int
cPLAYER_DATA::getCurrentStatePointSum()
{
	int	iSum	=	m_sStrength+m_sAgility+m_sConstitution+m_sWisdom+m_sIntelligence+m_sCharisma+m_sLuck+m_wLevelPoint-90;

	return	iSum;
}

//
//	현재 스킬포인트의 합
int
cPLAYER_DATA::getCurrentStatePointSumByLevel()
{
	int	iSum	=	(m_iLevel-1)*5;

	iSum		+=	m_bf4CH5StateBonusCount*5;
	iSum		+=	c_aBonusStatePointForRebirth[m_bf4RebirthCount];

	return	iSum;
}

//
//	현재 스킬포인트의 합
int
cPLAYER_DATA::getCurrentSkillPointSum()
{
	int	iSkillPoint	=	m_dwSkillExperience;

	for (int i=0;i<dABILITY_COUNT;i++)
	{
		if (m_aAbility[i].m_wSkill	==	0xffff	)
			continue;
		if (m_aAbility[i].m_wLevel	==	0		)
			continue;

		int	iPoint	=	((cABILITY*)&m_aAbility[i])->getSkillPoint();

		iSkillPoint	+=	iPoint;
	}

	return	iSkillPoint-1;	//	가장 기본 스킬
}

//
//	레벨을 보고 스킬포인트를 판단한다.
int
cPLAYER_DATA::getCurrentSkillPointByLevel()
{
	int	iSkillPoint		=	0;

	for (int i=2;i<=m_iLevel;i++)
		iSkillPoint	+=	min(i,100);

	DWORD	dwLevelupExperience		=	g_aExpTable[m_iLevel];
	DWORD	dwNextSkillPoint		=	min(m_iLevel+1,100);
	LONGLONG	llExp				=	m_iExperience;
	llExp							*=	dwNextSkillPoint;

	if	(dwLevelupExperience	!=	0)
		llExp								/=	dwLevelupExperience;

	DWORD	dwCurrentLevelSkillPoint=	(DWORD)llExp;
	iSkillPoint						+=	dwCurrentLevelSkillPoint;	//	경험치에 의한 보정

	if	(m_wBonusSkillPoint	!=	0xffff)	
		iSkillPoint					+=	m_wBonusSkillPoint;

	int		iBonusPoint					=	m_bf4CH5SkillBonusCount;

	iSkillPoint							+=	iBonusPoint*100;
	iSkillPoint							+=	c_aBonusSkillPointForRebirth[m_bf4RebirthCount];

	return	iSkillPoint;
}

