//	스킬 포인트 초기화	
BOOL
cPLAYER_DATA::resetSkillPoint()
{
	// TODO: Add your control notification handler code here
	if (m_wJob == dJOB_WEREWOLF		)	m_wJob = dJOB_WIZARD;
	if (m_wJob == dJOB_FALLEN_ANGEL	)	m_wJob = dJOB_PRIEST;
	if (m_wJob == dJOB_DEVIL		)	m_wJob = dJOB_NECROMANCER;
	if (m_wJob == dJOB_MAGICAL_GIRL	)	m_wJob = dJOB_PRINCESS;

	cPLAYER_DATA	*lpJob	=	&g_aPlayerDefaultJobData[m_wJob];

	{
		int	iSkillPoint		=	0;

		for (int i=2;i<=m_iLevel;i++)
			iSkillPoint	+=	min(i,100);

		DWORD		dwLevelupExperience		=	g_aExpTable[m_iLevel];
		DWORD		dwNextSkillPoint		=	min(m_iLevel+1,100);
		LONGLONG	llExp					=	m_iExperience;
		llExp								*=	dwNextSkillPoint;
		llExp								/=	dwLevelupExperience;

		DWORD		dwCurrentLevelSkillPoint=	(DWORD)llExp;

		iSkillPoint							+=	dwCurrentLevelSkillPoint;	//	경험치에 의한 보정

		if	(m_wBonusSkillPoint!=	0xffff)	
			iSkillPoint		+=	m_wBonusSkillPoint;

		int	iCH5SkillBonus	=	m_bf4CH5SkillBonusCount;

		iSkillPoint			+=	iCH5SkillBonus*100;
		iSkillPoint			+=	c_aBonusSkillPointForRebirth[m_bf4RebirthCount];

		m_dwSkillExperience	=	iSkillPoint;
	}

	memcpy(m_aAbility,lpJob->m_aAbility,sizeof(m_aAbility));

	return	TRUE;
}

